const s1 = sketch('top'); s1.polygon([[0,0],[40,0],[40,30],[0,30]]);
const plate = extrude(s1, 10);
const s2 = sketch('top', 10); s2.circle(6, { at: [10, 15] });
const p = pocket(s2, plate, 10);
mirror(p, 'left-right', { at: 20 });

